var m = tree.current_scene
var u = GameState.get_unit("U_GRETCHIN_A")
var lo = Vector2(INF, INF)
var hi = Vector2(-INF, -INF)
var sum = Vector2.ZERO
var n = 0
for md in u.models:
	if not md.get("alive", true):
		continue
	var bt = md.get("base_type", null)
	if bt != null and str(bt) != "circular":
		return -1.0
	var p = Vector2(float(md.position.x), float(md.position.y))
	var r = float(md.base_mm) / 25.4 * 40.0 / 2.0
	lo = Vector2(min(lo.x, p.x - r), min(lo.y, p.y - r))
	hi = Vector2(max(hi.x, p.x + r), max(hi.y, p.y + r))
	sum += p
	n += 1
m.set_meta("t14_box", Rect2(lo, hi - lo))
m.set_meta("t14_box_mean", sum / max(n, 1))
m.set_meta("t14_box_n", n)
return n

# The free area computed HERE from the HUD panels' own rects (not from
# Main.get_board_view_rect): below the top bar, above the phase strip,
# right of the game log (and the roster strip if open), left of HUD_Right.
var m = tree.current_scene
for n in ["HUD_Bottom", "PhaseStrip", "GameLogPanel", "HUD_Right"]:
	if not m.get_node(n).is_visible_in_tree():
		return "%s hidden" % n
var top = m.get_node("HUD_Bottom").get_global_rect().end.y
var bottom = m.get_node("PhaseStrip").get_global_rect().position.y
var left = m.get_node("GameLogPanel").get_global_rect().end.x
var lr = m.get_node_or_null("LeftRoster")
if lr != null and lr.is_visible_in_tree():
	left = max(left, lr.get_global_rect().end.x)
var right = m.get_node("HUD_Right").get_global_rect().position.x
var free = Rect2(left, top, right - left, bottom - top)
m.set_meta("t14_free", free)
return str(free)

var m = tree.current_scene
var box: Rect2 = m.get_meta("t14_box")
var a = m.world_to_screen_position(box.position)
var b = m.world_to_screen_position(box.end)
return Rect2(a, b - a).abs().intersects(m.get_viewport().get_visible_rect())

