# The fit zoom computed HERE: the box plus 5" (200 px) of table on each
# side must fit the free area, and the zoom stops at 1.2x.
var m = tree.current_scene
var box: Rect2 = m.get_meta("t14_box")
var free: Rect2 = m.get_meta("t14_free")
var z = min(min(free.size.x / (box.size.x + 400.0), free.size.y / (box.size.y + 400.0)), 1.2)
m.set_meta("t14_expected_zoom", z)
return abs(m.view_zoom - z)

var m = tree.current_scene
var box: Rect2 = m.get_meta("t14_box")
return m.world_to_screen_position(box.get_center()).distance_to((m.get_meta("t14_free") as Rect2).get_center())

# Every alive base of the mob, drawn through BoardRoot's transform, inside
# the free area (so clear of every HUD panel).
var m = tree.current_scene
var free: Rect2 = m.get_meta("t14_free")
var z = m.view_zoom
var bad = []
var n = 0
for md in GameState.get_unit("U_GRETCHIN_A").models:
	if not md.get("alive", true):
		continue
	n += 1
	var r = float(md.base_mm) / 25.4 * 40.0 / 2.0 * z
	var sp = m.world_to_screen_position(Vector2(float(md.position.x), float(md.position.y)))
	if not free.encloses(Rect2(sp - Vector2(r, r), Vector2(2.0 * r, 2.0 * r))):
		bad.append(str(md.get("id", "?")))
return "%d/%d" % [bad.size(), n]

# Tier B 'Other units in frame if they fit': every model of another unit
# whose whole base lies within 5" (200 px) of the mob's footprint is drawn
# inside the free area.
var m = tree.current_scene
var free: Rect2 = m.get_meta("t14_free")
var ring: Rect2 = (m.get_meta("t14_box") as Rect2).grow(200.0)
var z = m.view_zoom
var near = 0
var bad = []
for uid in GameState.state.units:
	if uid == "U_GRETCHIN_A":
		continue
	for md in GameState.state.units[uid].get("models", []):
		if not md.get("alive", true):
			continue
		var pos = md.get("position", null)
		if typeof(pos) != TYPE_DICTIONARY or pos.get("x") == null:
			continue
		var p = Vector2(float(pos.x), float(pos.y))
		var r = Measurement.base_extent_px(md)
		if not ring.encloses(Rect2(p - Vector2(r, r), Vector2(2.0 * r, 2.0 * r))):
			continue
		near += 1
		var rs = r * z
		var sp = m.world_to_screen_position(p)
		if not free.encloses(Rect2(sp - Vector2(rs, rs), Vector2(2.0 * rs, 2.0 * rs))):
			bad.append("%s/%s" % [uid, str(md.get("id", "?"))])
m.set_meta("t14_near", near)
return bad.size()

var m = tree.current_scene
var s = m.get_meta("t14_samples", [])
var z0 = float(m.get_meta("t14_z0"))
var z1 = m.view_zoom
var n = 0
for e in s:
	var z = float(e["vz"])
	if abs(z - z0) > 0.001 and abs(z - z1) > 0.001:
		n += 1
return n

var m = tree.current_scene
var s = m.get_meta("t14_samples", [])
var z0 = float(m.get_meta("t14_z0"))
var z1 = m.view_zoom
var prev = z0
var away = 0
for e in s:
	var z = float(e["vz"])
	if (z - prev) * (z1 - z0) < -0.000001:
		away += 1
	prev = z
return away

# The mob's centre heads straight for the middle: each sampled frame is on the
# line from where it started to the free area's centre, and never further from
# the centre than the frame before.
var m = tree.current_scene
var s = m.get_meta("t14_samples", [])
var a: Vector2 = m.get_meta("t14_start_screen")
var b: Vector2 = (m.get_meta("t14_free") as Rect2).get_center()
var prev = a.distance_to(b)
var worst = 0.0
for e in s:
	var p: Vector2 = e["sc"]
	worst = max(worst, Geometry2D.get_closest_point_to_segment(p, a, b).distance_to(p))
	var d = p.distance_to(b)
	if d > prev + 0.5:
		return 1000.0 + d - prev
	prev = d
return worst

