if not m.fit_view_to_selection("U_KOMMANDOS_A"):
	return 998.0
var p = GameState.get_unit("U_BATTLEWAGON_A").models[0].position
return m.camera.position.distance_to(Vector2(float(p.x), float(p.y)))

