# The line's two ends sit exactly 5" of table (200 px * zoom) in from the
# game log and from the right panel.
var m = tree.current_scene
var box: Rect2 = m.get_meta("t14_wide_box")
var free: Rect2 = m.get_meta("t14_free")
var want = 200.0 * m.view_zoom
var left = m.world_to_screen_position(box.position).x - free.position.x
var right = free.end.x - m.world_to_screen_position(box.end).x
return max(abs(left - want), abs(right - want))

